import sys

def main():
    line = sys.stdin.readline()
    letters = 0
    digits = 0
    spaces = 0
    for ch in line:
        if 'a' <= ch <= 'z':
            letters += 1
        elif 'A' <= ch <= 'Z':
            letters += 1
        elif '0' <= ch <= '9':
            digits += 1
        elif ch == ' ':
            spaces += 1
    print(letters)
    print(digits)
    print(spaces)

if __name__ == "__main__":
    main()
